"""
Final hypothesis: For each color, compute max(height_in_top, height_in_bot).
Output = color with larger max height. If tied, output=2.
"""

def get_max_height_in_grid(grid, color):
    """Get max height of continuous block of color in the entire grid (excluding separator)."""
    top = grid[:len(grid)//2]
    bot = grid[len(grid)//2+1:]

    def max_height(region):
        heights = []
        for c in range(len(region[0])):
            i = 0
            while i < len(region):
                if region[i][c] == color:
                    height = 1
                    j = i + 1
                    while j < len(region) and region[j][c] == color:
                        height += 1
                        j += 1
                    heights.append(height)
                    i = j
                else:
                    i += 1
        return max(heights) if heights else 0

    return max(max_height(top), max_height(bot))

